/**
 * Barcode and QR images written by BWIPP (Barcode Writer in Pure PostScript) through treepoem and rendered by
 * Ghostscript, as base64 PNG literals, plus three degraded copies in the style of a photograph of a screen.
 * Written by make-fixtures.py on 2026-10-03 with treepoem 3.29.0,
 * Pillow 12.3.0, numpy 2.5.3, Ghostscript 10.07.1 and Python 3.14.3.
 * Do not edit by hand: change the script and run it again.
 */

export interface IndependentCode {
  /** A short name used in test messages and in the lists of documented exceptions. */
  name: string;
  /** The symbology as the writer names it. */
  writtenAs: string;
  /** The data given to the writer. */
  data: string;
  /** The reading engine's own name for the symbology the reader should report. */
  format: string;
  /** The text the reader should report. */
  text: string;
  /** A base64 PNG. */
  png: string;
}

